cases.script:
strip() { /usr/bin/sed -E 's/^[^:]*: line [0-9]+: //' "$1" | /usr/bin/tr '\n' '|'; }
show() { printf '%s status=%s out=' "$1" "$2"; /usr/bin/tr '\n' '|' < /tmp/rf.out; printf ' err='; strip /tmp/rf.err; echo; }
r() { local l=$1; shift; "$@" >/tmp/rf.out 2>/tmp/rf.err; show "$l" $?; }
u() { local g=--clear-groups; [[ $3 ]] && g=--groups=$3
  /usr/bin/setpriv --reuid=2000 --regid=2000 $g -- "$BASH" --noprofile --norc -c "$2" >/tmp/rf.out 2>/tmp/rf.err; show "$1" $?; }
RT=/tmp/rt; /usr/bin/mkdir -p $RT
seed() { /usr/bin/python3 -c 'import sys; n=int(sys.argv[2]); open(sys.argv[1],"wb").write(bytes((i*7+i//251)%256 for i in range(n)))' "$1" "$2"; }
sz() { /usr/sbin/blockdev --getsize64 "$1"; }
sha() { /usr/bin/sha256sum < "$1" | /usr/bin/cut -c1-16; }
# udev probes each new loop device; settle before detaching so the detach is
# immediate, and wait for sysfs to drop the association before the next attach.
settle() { /usr/bin/udevadm settle -t 10 >/dev/null 2>&1; }
gone() { local x=${1#/dev/} i; for ((i=0;i<50;i++)); do [[ -e /sys/block/$x/loop/backing_file ]] || return 0; /usr/bin/sleep 0.1; done; echo "  $x still attached"; }
att() { /usr/sbin/losetup "$@"; settle; }
detach() { local d; for d; do /usr/sbin/losetup -d $d; gone $d; done; }
nx=0; mkext() { local i=$1 s=$2 m=$3; shift 3; nx=$((nx+1))
  /usr/bin/truncate -s $s $i && /usr/sbin/mkfs.ext4 -q -F -O ^has_journal -E nodiscard,lazy_itable_init=0 \
    -U 0b0e0e0e-1111-4222-8333-44444444444$nx "$@" $i && dev=$(att -f --show $i) && /usr/bin/mkdir -p $m &&
    /usr/bin/mount $dev $m || { echo SETUP-FAILED; exit 99; }; }
probe() { if /usr/sbin/fsfreeze -f $M 2>/dev/null; then /usr/sbin/fsfreeze -u $M; echo "  frozen=no"; else echo "  frozen=yes"; fi; }
trap '/usr/sbin/fsfreeze -u $M >/dev/null 2>&1' EXIT
cd $RT; M=$RT/mnt; mkext img 8M $M; echo data > $M/f
r freeze fsfreeze -f $M; probe
r read-frozen /usr/bin/cat $M/f
/usr/bin/dd if=/dev/zero of=$M/w bs=4k count=2 conv=fsync status=none & wp=$!
/usr/bin/sleep 1; kill -0 $wp 2>/dev/null && echo "  writer blocked" || echo "  writer finished early"
r thaw fsfreeze -u $M
wait $wp; echo "  writer status=$? size=$(/usr/bin/stat -c %s $M/w)"; probe
r freeze-long fsfreeze --freeze $M; probe
r unfreeze-long fsfreeze --unfreeze $M; probe
r thaw-unfrozen fsfreeze -u $M; probe
/usr/bin/ln -s mnt lnk
r freeze-link fsfreeze -f lnk; probe
r thaw-link fsfreeze -u lnk; probe
r write-after /usr/bin/dd if=/dev/zero of=$M/w2 bs=4k count=1 conv=fsync status=none
trap - EXIT; cd /tmp/parity-case; /usr/bin/umount $M; detach $dev; echo teardown=ok

