att() { /usr/sbin/losetup "$@"; settle; }
detach() { local d; for d; do /usr/sbin/losetup -d $d; gone $d; done; }
SC=/opt/bashos-parity/harness/helpers/system-seccomp.py SQ=/opt/bashos-parity/harness/helpers/system-sequence.py
j() { PYTHONDONTWRITEBYTECODE=1 /usr/bin/python3 $2 -- "$BASH" --noprofile --norc -c "$3" >/tmp/rf.out 2>/tmp/rf.err; show "$1" $?; }
cd $RT; seed a.img 65536
state() { local b l=; for b in /sys/block/loop*/loop/backing_file; do [[ -e $b ]] && l+=" ${b#/sys/block/}"; done; echo "  attached:${l:- none}"; /usr/sbin/losetup -a | /usr/bin/sed -E 's/\[[0-9a-f]+\]:[0-9]+ //; s/^/  /'; }
cleanup() { local b x; for b in /sys/block/loop*/loop/backing_file; do [[ -e $b ]] || continue; x=${b#/sys/block/}; detach /dev/${x%%/*}; done; }
state
j find-free "$SC --errno ioctl:ENOSPC:1=0x4c82" "losetup -f"; state
j find-attach "$SC --errno ioctl:ENOSPC:1=0x4c82" "losetup -f --show $RT/a.img"; state
cleanup
j rollback "$SC --errno ioctl:ENOTTY:1=0x4c0a --errno ioctl:EINVAL:1=0x4c04" "losetup -f --show $RT/a.img"; state
cleanup
j rollback-fails "$SC --errno ioctl:ENOTTY:1=0x4c0a --errno ioctl:EINVAL:1=0x4c04 --errno ioctl:EIO:1=0x4c01" "losetup -f --show $RT/a.img"; state
cleanup; state; echo teardown=ok
